use data::*;

macro_rules! implies {
  ($lhs: expr, $rhs: expr) => {
    !$lhs || $rhs
  };
}

macro_rules! impliesL {
  ($lhs: expr, $rhs: expr) => {
    !$lhs | $rhs
  };
}

/** Compute Entrypoint Contract
  *
  * guarantee C_Output_Range
  *   C output range
  * @param api_Input1 incoming data port
  * @param api_Input2 incoming data port
  * @param api_Output outgoing data port
  */
pub fn compute_spec_C_Output_Range_guarantee(
  api_Input1: i32,
  api_Input2: i32,
  api_Output: i32) -> bool
{
  api_Output == api_Input1 + api_Input2
}

/** CEP-T-Guar: Top-level guarantee contracts for c's compute entrypoint
  *
  * @param api_Input1 incoming data port
  * @param api_Input2 incoming data port
  * @param api_Output outgoing data port
  */
pub fn compute_CEP_T_Guar(
  api_Input1: i32,
  api_Input2: i32,
  api_Output: i32) -> bool
{
  let r0: bool = compute_spec_C_Output_Range_guarantee(api_Input1, api_Input2, api_Output);

  return r0;
}

/** CEP-Post: Compute Entrypoint Post-Condition for c
  *
  * @param api_Input1 incoming data port
  * @param api_Input2 incoming data port
  * @param api_Output outgoing data port
  */
pub fn compute_CEP_Post(
  api_Input1: i32,
  api_Input2: i32,
  api_Output: i32) -> bool
{
  // CEP-Guar: guarantee clauses of c's compute entrypoint
  let r0: bool = compute_CEP_T_Guar(api_Input1, api_Input2, api_Output);

  return r0;
}
